use lwe_rust::kyber::kem::{encaps_internal, EncapsulationKey};
use lwe_rust::kyber::pke::ML_KEM_512;

#[test]
fn test_fips203_encaps_kat() {
    let ek_hex = "";
    let m_hex = "DCACFE4DE1C115DA106ACD1EEFEAFDC7F0F4E5707453EE2D6B0D69D34CC0EF4A";
    let c_expected_hex = "";
    let k_expected_hex = "2D74374B55D29AA585E144A29BA4F0A96537A73B4F176C5527075F66E38E8858";

    let ek = hex::decode(ek_hex).unwrap();
    let m = hex::decode(m_hex).unwrap();
    let c_expected = hex::decode(c_expected_hex).unwrap();
    let k_expected = hex::decode(k_expected_hex).unwrap();

    let mut m_array = [0u8; 32];
    m_array.copy_from_slice(&m);

    let mut ek_array = [0u8; 800];
    ek_array.copy_from_slice(&ek);
    let ek_wrapped = EncapsulationKey(ek_array);
    let (k, c) = encaps_internal::<800, 768>(&ML_KEM_512, &ek_wrapped, &m_array);

    assert_eq!(k.0.as_slice(), k_expected, "Shared Secret (k) mismatch");
    assert_eq!(c.0.as_slice(), c_expected, "Ciphertext (c) mismatch");
}
